import sys, os, json, math, optax
import numpy as np
import jax
import jax.numpy as jnp
from typing import Dict, Any

# Import our verified HDP-RegCal network builder
sys.path.append('storage/noema/submissions')
from dual_path_hybrid_motif_heads_regcal import build_network as build_hdp_regcal

# Import system training utilities to access dataset builders
sys.path.append('storage/system')
import train_single as ts  # debugger can adjust name resolution if needed

BASE_SEED = 42
BATCH_SIZE = 64

def _define_hyperparameters():
    # Default reproducible HDP-RegCal config (matches paper defaults)
    return {
        'hidden_dim': 256,
        'd_model': 256,
        'kernel_size': 7,
        'dropout_rate': 0.10,
        'aggregator': 'mean_max',        # main path pooling
        'motif_kernel_size': 5,          # default motif kernel
        'regcal_l2': True,               # enable RegCal
        'head_dropout': 0.05,            # regression-family head dropout
        'learning_rate': 0.001,
        'grad_clip': 1.0
    }

def create_network(hparams):
    # Standard network creation; training/eval loop calls apply(deterministic=...)
    return build_hdp_regcal(hparams.get('d_output', 1), hparams.get('task_type', 'regression'), hparams)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=0.01)
    )

# ---------- Analysis helpers (run only in complete) ----------

def _task_spec(dataset: str):
    # Map dataset name to task type and d_output
    if dataset in ("APA", "CRI-Off", "CRI-On", "MRL"):
        return "regression", 1
    if dataset == "PRS":
        return "multilabel_regression", 3
    if dataset == "Modif":
        return "multilabel_classification", 12
    if dataset == "ncRNA":
        return "multiclass_classification", 13
    raise ValueError(f"Unknown dataset: {dataset}")

def _summarize(arr):
    arr = np.asarray(arr).reshape(-1)
    qs = np.quantile(arr, [0.05, 0.25, 0.50, 0.75, 0.95])
    return dict(
        mean=float(arr.mean()), std=float(arr.std()),
        q05=float(qs[0]), q25=float(qs[1]), q50=float(qs[2]),
        q75=float(qs[3]), q95=float(qs[4]), n=int(arr.size)
    )

def _maybe_get_val_iter(dataset_name: str, hparams: Dict[str, Any], batch_size: int = 256):
    """
    Use system loader API exposed via train_single.py. We attempt a few common builder names
    and let the automatic debugger adjust if station internals differ.
    """
    # Prefer an explicit function if present
    if hasattr(ts, 'build_val_iterator'):
        return ts.build_val_iterator(dataset_name, batch_size)
    if hasattr(ts, 'get_val_loader'):
        return ts.get_val_loader(dataset_name, batch_size)
    if hasattr(ts, 'make_val_dataloader'):
        return ts.make_val_dataloader(dataset_name, batch_size)
    # Fallback: generic builder using defaults inside train_single (debugger can patch)
    if hasattr(ts, 'build_dataloader'):
        return ts.build_dataloader(dataset_name, split='val', batch_size=batch_size)
    raise RuntimeError("No recognized val iterator builder in system/train_single.py")

def _collect_z_pre_norms(params, dataset_name: str, hparams: Dict[str, Any]):
    """
    Reconstruct the same module, apply with capture_intermediates, and collect ||z_pre||2 on the val split.
    Only for regression-family datasets (APA, CRI-Off, CRI-On, MRL, PRS).
    """
    task_type, d_out = _task_spec(dataset_name)
    # Rebuild network module with the same hparams used for this dataset
    hp = dict(hparams)
    hp['task_type'] = task_type
    hp['d_output'] = d_out
    network = build_hdp_regcal(d_out, task_type, hp)

    # Build validation iterator (bigger batch for speed; no gradients)
    try:
        val_iter = _maybe_get_val_iter(dataset_name, hp, batch_size=256)
    except Exception as e:
        print(f"[NormCapture] Failed to build val iterator for {dataset_name}: {e}")
        return None

    norms = []
    processed = 0
    max_samples = 10000  # cap for speed

    def apply_and_capture(x_np):
        x = jnp.asarray(x_np)
        # capture_intermediates + mutable to fetch sow('intermediates','z_pre',...)
        y, col = network.network.apply(
            {'params': params}, x,
            deterministic=True,
            capture_intermediates=True,
            mutable=['intermediates']
        )
        # Extract all 'z_pre' tensors
        if 'intermediates' in col:
            for scope, feats in col['intermediates'].items():
                if isinstance(feats, dict) and 'z_pre' in feats:
                    for t in feats['z_pre']:
                        z_pre = np.array(t)  # [B, H]
                        n = np.linalg.norm(z_pre, ord=2, axis=-1)  # [B]
                        norms.append(n)

    for batch in val_iter:
        # train_single typically returns a dict or tuple; support common patterns
        xb = batch['inputs'] if isinstance(batch, dict) and 'inputs' in batch else batch[0]
        apply_and_capture(xb)
        processed += xb.shape[0]
        if processed >= max_samples:
            break

    if norms:
        norms = np.concatenate(norms, axis=0)
        return _summarize(norms)
    return None

def complete(params, opt_state, trial_data):
    ds = trial_data.get('dataset')
    val = trial_data.get('val_metric')
    print(f"[Complete] {ds} final val_metric={val}")

    # Only collect for regression-family datasets
    if ds not in ("APA", "CRI-Off", "CRI-On", "MRL", "PRS"):
        return

    # Get the hyperparameters used
    hparams = trial_data.get('hyperparameters', {}) or {}

    os.makedirs('storage/noema/results/hdp_regcal_norms', exist_ok=True)
    out_path = f"storage/noema/results/hdp_regcal_norms/{ds}.json"

    try:
        summary = _collect_z_pre_norms(params, ds, hparams)
        if summary is not None:
            with open(out_path, 'w') as f:
                json.dump({'dataset': ds, 'summary': summary, 'seed': trial_data.get('seed')}, f, indent=2)
            print(f"[NormCapture] Saved {ds} z-norm summary -> {out_path}")
        else:
            print(f"[NormCapture] No norms collected for {ds}")
    except Exception as e:
        print(f"[NormCapture] Error during collection for {ds}: {e}")
